-- SQL queries of a project (Go strings, concatenations with package
-- constants, squirrel chains, goose migrations, sqlc files), their tree and
-- its groupings, SQL highlighting inside Go strings, TODO comments: the
-- ripgrep pattern, ]t / [t and the colours of the tags. The fixture project
-- is written here; generated files and vendor/ must be left out.
local root = vim.fn.tempname()

local function write(path, text)
    vim.fn.mkdir(vim.fn.fnamemodify(root .. "/" .. path, ":h"), "p")
    vim.fn.writefile(vim.split(text, "\n", { plain = true }), root .. "/" .. path)
end

write("go.mod", "module example.com/shop\n\ngo 1.23")
write("internal/repo/tables.go", [[
package repo

const ordersTable = "orders"]])
write("internal/repo/order.go", [[
package repo

import (
	"context"
	"fmt"

	sq "github.com/Masterminds/squirrel"
)

const getOrderQuery = `
	SELECT o.id, o.status, u.name
	FROM orders o
	JOIN users u ON u.id = o.user_id
	WHERE o.id = $1`

type Repo struct{}

func (r *Repo) Create() string {
	return "INSERT INTO orders (id, status) VALUES ($1, $2) ON CONFLICT (id) DO UPDATE SET status = excluded.status"
}

func (r *Repo) MarkPaid() (string, []any, error) {
	return sq.Update(ordersTable).Set("status", "paid").Where(sq.Eq{"id": 1}).ToSql()
}

func (r *Repo) List() (string, []any, error) {
	return sq.Select("o.id").From("orders o").LeftJoin("payments p ON p.order_id = o.id").ToSql()
}

func (r *Repo) Archive() string {
	return "WITH old AS (SELECT id FROM orders WHERE created_at < now()) " +
		"DELETE FROM " + ordersTable + " USING old WHERE orders.id = old.id"
}

func (r *Repo) Count(ctx context.Context) string {
	ctx = context.TODO()
	_ = ctx
	return fmt.Sprintf("SELECT count(*) FROM %s WHERE status = $1", "orders")
}

func notQueries() error {
	cache.Delete("key")
	return fmt.Errorf("update order: %w", nil)
}

// TODO: paginate List
// FIXME(team): archive in batches]])
write("internal/repo/order_mock.go", [[
// Code generated by MockGen. DO NOT EDIT.

package repo

const ghost = "SELECT id FROM ghost_table"]])
write("vendor/example.com/lib/lib.go", [[
package lib

const q = "SELECT id FROM vendored"]])
write("migrations/0001_init.sql", [[
-- +goose Up
CREATE TABLE orders (
    id bigint PRIMARY KEY,
    status text NOT NULL, -- TODO: enum
    user_id bigint REFERENCES users (id) ON DELETE CASCADE
);
CREATE INDEX orders_status_idx ON orders (status);

-- +goose StatementBegin
CREATE FUNCTION touch() RETURNS trigger AS $$
BEGIN
    UPDATE orders SET status = 'x';
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
-- +goose StatementEnd

-- +goose Down
DROP TABLE orders;]])
write("queries/orders.sql", [[
-- name: GetOrder :one
SELECT * FROM orders WHERE id = $1;

-- name: ListUserOrders :many
SELECT o.* FROM orders o, users u WHERE u.id = o.user_id AND u.id = $1;]])

local sql_nav = require("sql_nav")

-- The analyser on its own.
local function analyzed(sql)
    local info = sql_nav.analyze(sql)
    return info and (info.kind .. " " .. table.concat(info.tables, ",")) or "-"
end
for sql, want in pairs({
    ["select a from orders o join users u on u.id = o.uid"] = "SELECT orders,users",
    ["SELECT extract(year FROM created_at) FROM orders"] = "SELECT orders",
    ["select * from unnest($1::int[]) as t(id)"] = "SELECT ",
    ["UPDATE ONLY public.orders SET a = 1 FROM users WHERE x FOR UPDATE"] = "UPDATE public.orders,users",
    ["insert into \"Order\" (id) select id from tmp"] = "INSERT Order,tmp",
    ["DELETE FROM orders WHERE id IN (SELECT order_id FROM refunds)"] = "DELETE orders,refunds",
    ["ALTER TABLE IF EXISTS orders ADD COLUMN x int"] = "ALTER orders",
    ["DROP TABLE IF EXISTS a, b"] = "DROP a,b",
    ["TRUNCATE orders, payments RESTART IDENTITY"] = "TRUNCATE orders,payments",
    ["CREATE UNIQUE INDEX CONCURRENTLY i ON ONLY orders (id)"] = "CREATE orders",
    ["update order: %w"] = "-",
    ["select an option"] = "-",
    ["create order"] = "-",
    ["with retries"] = "-",
}) do
    assert(analyzed(sql) == want, sql .. " → " .. analyzed(sql) .. ", want " .. want)
end
print("SQL_ANALYZE_OK")

-- Collected queries.
local queries = sql_nav.collect(root)
local by_owner = {}
for _, item in ipairs(queries) do
    assert(not item.path:find("vendor/", 1, true) and not item.path:find("_mock.go", 1, true),
        "generated and vendored files are skipped: " .. item.path)
    local key = item.owner .. " " .. item.kind
    by_owner[key] = by_owner[key] or item
end
local function expect(owner_kind, tables)
    local item = by_owner[owner_kind]
    assert(item, "missing query " .. owner_kind .. " in " .. vim.inspect(vim.tbl_keys(by_owner)))
    assert(table.concat(item.tables, ",") == tables,
        owner_kind .. " tables " .. table.concat(item.tables, ",") .. ", want " .. tables)
    return item
end
expect("getOrderQuery SELECT", "orders,users")
expect("(*Repo) Create INSERT", "orders")
local paid = expect("(*Repo) MarkPaid UPDATE", "orders")
expect("(*Repo) List SELECT", "orders,payments")
expect("(*Repo) Archive DELETE", "orders")
expect("(*Repo) Count SELECT", "")
expect("0001_init CREATE", "orders") -- the table; then its index and a function
expect("0001_init ↓ DROP", "orders")
expect("GetOrder SELECT", "orders")
expect("ListUserOrders SELECT", "orders,users")
assert(#queries == 12, "12 queries, got " .. #queries .. ": " .. vim.inspect(vim.tbl_keys(by_owner)))
assert(not by_owner["notQueries DELETE"] and not by_owner["notQueries UPDATE"], "cache.Delete and error text are not SQL")
local order_lines = vim.fn.readfile(root .. "/internal/repo/order.go")
assert(order_lines[paid.line]:find("sq.Update(ordersTable)", 1, true), "builder position: " .. order_lines[paid.line])
print("SQL_COLLECT_OK queries=" .. #queries)

-- Groupings.
local function names(groups)
    local out = {}
    for _, group in ipairs(groups) do
        out[#out + 1] = (group.name ~= "" and group.name or "-") .. "=" .. #group.queries
    end
    return table.concat(out, " ")
end
local by_table = sql_nav.groups(queries, "table", root)
assert(names(by_table) == "orders=10 payments=1 users=2 -=2", "by table: " .. names(by_table))
assert(by_table[1].preview.path:match("0001_init%.sql$") and by_table[1].preview.line == 2,
    "orders previews its CREATE TABLE")
assert(by_table[1].queries[1].kind == "CREATE" and by_table[1].queries[#by_table[1].queries].kind == "DELETE",
    "schema first, writes last")
local by_kind = sql_nav.groups(queries, "kind", root)
assert(names(by_kind) == "CREATE=3 DROP=1 SELECT=5 INSERT=1 UPDATE=1 DELETE=1", "by kind: " .. names(by_kind))
local by_file = sql_nav.groups(queries, "file", root)
assert(names(by_file) == "internal/repo/order.go=6 migrations/0001_init.sql=4 queries/orders.sql=2",
    "by file: " .. names(by_file))
print("SQL_GROUPS_OK")

-- The tree window.
local source_win = vim.api.nvim_get_current_win()
local tree = sql_nav.open(root)
assert(tree and vim.api.nvim_get_current_win() == tree, "the tree opens focused")
local tree_buf = vim.api.nvim_win_get_buf(tree)
local tree_lines = vim.api.nvim_buf_get_lines(tree_buf, 0, -1, false)
local title = vim.api.nvim_win_get_config(tree).title
title = type(title) == "table" and title[1][1] or title
assert(title:find("SQL · 12 queries · by table", 1, true), "title: " .. vim.inspect(title))
assert(tree_lines[1] == "orders  10", "first group: " .. tree_lines[1])
assert(vim.fn.foldclosed(1) == 1, "groups start closed when they do not fit")
local function press(lhs)
    local map = vim.fn.maparg(lhs, "n", false, true)
    assert(map.callback, lhs .. " is mapped in the tree")
    map.callback()
end
press("<CR>")
assert(vim.fn.foldclosed(1) == -1, "Enter on a group opens it")
local paid_row
for row, line in ipairs(tree_lines) do
    if line:find("(*Repo) MarkPaid", 1, true) and row <= 11 then
        paid_row = row
    end
end
assert(paid_row and tree_lines[paid_row]:find("UPDATE", 1, true), "MarkPaid row in the orders group")
vim.api.nvim_win_set_cursor(tree, { 2, 0 })
vim.api.nvim_exec_autocmds("CursorMoved", { buffer = tree_buf })
local preview_text
for _, win in ipairs(vim.api.nvim_list_wins()) do
    local config = vim.api.nvim_win_get_config(win)
    if win ~= tree and config.relative ~= "" then
        local buf = vim.api.nvim_win_get_buf(win)
        preview_text = table.concat(vim.api.nvim_buf_get_lines(buf, 0, -1, false), "\n")
    end
end
assert(preview_text and preview_text:find("CREATE TABLE orders", 1, true), "preview shows the migration")

-- Enter on a query opens it in the source window.
vim.api.nvim_win_set_cursor(tree, { paid_row, 0 })
press("<CR>")
assert(not vim.api.nvim_win_is_valid(tree), "the tree closes on a jump")
assert(vim.api.nvim_get_current_win() == source_win, "jump lands in the source window")
assert(vim.api.nvim_buf_get_name(0):match("internal/repo/order%.go$"), "opened order.go")
assert(vim.api.nvim_win_get_cursor(0)[1] == paid.line, "cursor on the builder")

-- Tab regroups.
tree = sql_nav.open(root)
press("<Tab>")
tree = vim.api.nvim_get_current_win()
title = vim.api.nvim_win_get_config(tree).title
title = type(title) == "table" and title[1][1] or title
assert(title:find("by kind", 1, true), "Tab regroups by kind: " .. vim.inspect(title))
assert(vim.api.nvim_buf_get_lines(0, 0, 1, false)[1] == "CREATE  3", "kind groups")
press("q")
print("SQL_TREE_OK")

-- SQL highlighting inside Go strings (order.go is the current buffer).
vim.api.nvim_set_current_win(source_win)
vim.treesitter.get_parser(0):parse(true)
local go_lines = vim.api.nvim_buf_get_lines(0, 0, -1, false)
local function langs_at(needle, offset)
    for row, line in ipairs(go_lines) do
        local col = line:find(needle, 1, true)
        if col then
            local langs = {}
            for _, capture in ipairs(vim.treesitter.get_captures_at_pos(0, row - 1, col - 1 + (offset or 0))) do
                langs[capture.lang] = langs[capture.lang] or {}
                langs[capture.lang][capture.capture] = true
            end
            return langs, row, col - 1 + (offset or 0)
        end
    end
    error("no line with " .. needle)
end
assert(langs_at("SELECT o.id, o.status").sql, "multi-line raw string is SQL")
assert(langs_at("INSERT INTO orders").sql, "interpreted string is SQL")
assert(not langs_at('"update order: %w"', 1).sql, "an error message is not SQL")
print("SQL_HIGHLIGHT_OK")

-- TODO comments.
local todo_langs, todo_row, todo_col = langs_at("TODO: paginate")
assert(todo_langs.comment and todo_langs.comment["comment.todo"], "TODO tag coloured")
local fixme_langs, fixme_row, fixme_col = langs_at("FIXME(team)")
assert(fixme_langs.comment and fixme_langs.comment["comment.error"], "FIXME tag coloured")

vim.api.nvim_win_set_cursor(0, { 1, 0 })
local next_todo = vim.fn.maparg("]t", "n", false, true)
local previous_todo = vim.fn.maparg("[t", "n", false, true)
assert(next_todo.callback and previous_todo.callback, "]t and [t are mapped")
next_todo.callback()
assert(vim.deep_equal(vim.api.nvim_win_get_cursor(0), { todo_row, todo_col }),
    "]t skips context.TODO() and lands on the tag: " .. vim.inspect(vim.api.nvim_win_get_cursor(0)))
next_todo.callback()
assert(vim.deep_equal(vim.api.nvim_win_get_cursor(0), { fixme_row, fixme_col }), "]t again: FIXME")
previous_todo.callback()
assert(vim.api.nvim_win_get_cursor(0)[1] == todo_row, "[t back")

local found = vim.system({ "rg", "--line-number", "--no-heading", "--glob", "!vendor/**",
    "-e", require("todo").rg_pattern() }, { cwd = root, text = true }):wait()
local hits = vim.split(vim.trim(found.stdout), "\n", { trimempty = true })
local joined = table.concat(hits, "\n")
assert(#hits == 3, "three TODO comments: " .. vim.inspect(hits))
assert(joined:find("order.go:%d+:// TODO: paginate") and joined:find("order.go:%d+:// FIXME%(team%)")
    and joined:find("0001_init.sql:4:", 1, true), vim.inspect(hits))
print("TODO_OK")

vim.fn.delete(root, "rf")
print("SQL_TODO_SMOKE_OK")
